def verify(tools, answer):
    import json
    import re

    def safe_get(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def unwrap_result(tool_output):
        if isinstance(tool_output, dict):
            return tool_output.get('result', tool_output)
        return tool_output

    def extract_payload(ans):
        if not isinstance(ans, dict):
            return ans
        # Handle submit_result wrapper
        if 'submitted_data' in ans:
            return ans['submitted_data']
        if 'result' in ans:
            return ans['result']
        return ans

    try:
        payload = extract_payload(answer)
        if not payload:
            return {'passed': False, 'message': 'Empty or missing payload'}

        if not isinstance(payload, list):
            return {'passed': False, 'message': 'Payload must be a list'}

        # Get actual data from tools to verify content
        # Use get_how_to_build_content2 which likely contains framework components
        tool_output = tools['get_how_to_build_content2'](
            contains_keywords=['component', 'element', 'framework', 'policy', 'structure'],
            min_bullets=1
        )
        actual_data = unwrap_result(tool_output)

        if not actual_data or not isinstance(actual_data, list):
            return {'passed': False, 'message': 'Could not retrieve verification data from tools'}

        # Extract component names from answer
        answer_components = []
        for item in payload:
            if isinstance(item, dict):
                name = safe_get(item, 'component_name', '')
                if name and isinstance(name, str) and name.strip():
                    answer_components.append(name.strip().lower())

        if not answer_components:
            return {'passed': False, 'message': 'No valid component names found in answer'}

        # Extract actual component names from tool data
        actual_components = []
        for section in actual_data:
            if isinstance(section, dict):
                # Check text and bullets for component mentions
                text = safe_get(section, 'text', '')
                bullets = safe_get(section, 'bullets', [])

                # Look for component patterns in text
                if text and isinstance(text, str):
                    # Patterns that indicate structural components
                    patterns = [
                        r'(?:component|element|pillar|section|principle)s?\s*(?:include|are|consist of|:)\s*([^.!?]+)',
                        r'(?:must|should)\s+(?:include|contain|address)\s+([^.!?]+)',
                        r'(?:key|core|essential)\s+(?:components|elements|sections)\s*([^.!?]+)'
                    ]

                    for pattern in patterns:
                        matches = re.findall(pattern, text, re.IGNORECASE)
                        for match in matches:
                            # Split by commas, 'and', bullets, etc.
                            parts = re.split(r'[,;]|\band\b|\bor\b', match)
                            for part in parts:
                                part = part.strip()
                                if part and len(part) > 3 and not part.isdigit():
                                    actual_components.append(part.lower())

                # Check bullets
                if isinstance(bullets, list):
                    for bullet in bullets:
                        if isinstance(bullet, str):
                            bullet_lower = bullet.strip().lower()
                            if bullet_lower and len(bullet_lower) > 3:
                                actual_components.append(bullet_lower)

        # Remove duplicates and filter vague terms
        actual_components = list(set(actual_components))
        vague_terms = {'transparency', 'accountability', 'efficiency', 'value', 'quality', 
                      'compliance', 'risk', 'governance', 'procurement', 'policy'}
        actual_components = [c for c in actual_components 
                           if c not in vague_terms and len(c.split()) < 5]

        if not actual_components:
            return {'passed': False, 'message': 'Could not extract verification components from data'}

        # Verify at least some answer components match actual data
        matches_found = 0
        for ans_comp in answer_components:
            # Check for partial matches or keyword inclusion
            for act_comp in actual_components:
                if (ans_comp in act_comp or act_comp in ans_comp or 
                    any(word in ans_comp for word in act_comp.split()) or
                    any(word in act_comp for word in ans_comp.split())):
                    matches_found += 1
                    break

        # Calculate match ratio
        if answer_components:
            match_ratio = matches_found / len(answer_components)
        else:
            match_ratio = 0

        # Require reasonable match
        if match_ratio >= 0.3:  # At least 30% of components should match
            return True
        else:
            return {
                'passed': False,
                'message': f'Only {matches_found}/{len(answer_components)} components verified against source data',
                'details': {
                    'answer_components': answer_components[:10],  # First 10 for debugging
                    'actual_components_sample': actual_components[:10]
                }
            }

    except Exception as e:
        return {'passed': False, 'message': f'Verification error: {str(e)[:100]}'}

